   590	def _meta_builder_payload(
   591	    with_publishers,
   592	    publisher_values=None,
   593	    campaign_suffixes=None,
   594	    numeric_strings=False,
   595	):
   596	    publishers = publisher_values or (
   597	        ("facebook", "facebook", "instagram", "instagram") if with_publishers else (None,) * 4
   598	    )
   599	    raw_rows = []
   600	    suffixes = campaign_suffixes or (None,) * 4
   601	    for index, (day, publisher, spend, impressions, reach, engagement, views) in enumerate((
   602	        (1, publishers[0], 10, 1000, 800, 100, 500),
   603	        (2, publishers[1], 20, 2000, 1500, 200, 600),
   604	        (1, publishers[2], 30, 3000, 2200, 300, 700),
   605	        (2, publishers[3], 40, 4000, 3000, 400, 800),
   606	    )):
   607	        suffix = f"_{suffixes[index]}" if suffixes[index] else ""
   608	        metrics = {
   609	            "spend": spend,
   610	            "impressions": impressions,
   611	            "reach": reach,
   612	            "engagement": engagement,
   613	            "views": views,
   614	        }
   615	        if numeric_strings:
   616	            metrics = {
   617	                "social_spend": str(spend),
   618	                "impressions": str(impressions),
   619	                "reach": str(reach),
   620	                "total_interactions": str(engagement),
   621	                "unique_clicks": str(spend // 10),
   622	            }
   623	        item = {
   624	            "campaign_name": f"Meta launch {day}-{spend}{suffix}",
   625	            "date": f"2026-07-{day:02d}",
   626	            "metrics": metrics,
   627	        }
   628	        if publisher:
   629	            item["dimensions"] = {"publisher_platform": publisher}
   630	        raw_rows.append(item)
   631	    frame = process_api_response(raw_rows, "meta_ads", "client_1", "user_1")
   632	    context = _context({"platform": "meta_ads", "account_id": "act_1", "account_name": "Acme Foods"})
